// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Billowing Density
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Atlas)
// @param float _Columns = 1 [1 .. 4]
// @param float _Rows = 1 [1 .. 4]
// @param float _Seed = 321 [1 .. ~5000]
// @endgroup
// @group(Density)
// @param float _Radius = 0.31 [0.08 .. 0.43]
// @param float _Lobes = 9 [3 .. 18]
// @param float _PuffSize = 0.15 [0.04 .. 0.25]
// @param float _Warp = 0.055 [0 .. 0.18]
// @param float _Detail = 0.7 [0 .. 1]
// @param float _DetailScale = 4 [1 .. 16]
// @param float _Contrast = 1.3 [0.3 .. 4]
// @param float _Softness = 0.08 [0.005 .. 0.2]
// @param float _SourceMix = 0.25 [0 .. 1] // Blend the editable Noise layer into density.
// @endgroup
// @group(Tonal Shaping)
// @param float _Relief = 0 [0 .. 1] // Zero keeps RGB white for runtime tinting.
// @param float _Fold = 0 [0 .. 1]
// @endgroup

float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){


float2 count=max(1,round(float2(_Columns,_Rows)));
float2 local=LayerToLocal(uv);float2 cell=floor(local*count);
float2 tilePoint=frac(local*count)-.5;
float2 q=tilePoint;float seed=_Seed+dot(cell,float2(71,193));
float2 warp=float2(LearnNoise(q*4,seed),LearnNoise(q*4,seed+31))-.5;
q+=warp*_Warp*2;
float density=0;
for(int k=0;k<18;k++){
 if(k>=round(_Lobes))break;
 float h=LearnHash(float2(k+seed,19)),h2=LearnHash(float2(k,seed+7));
 float theta=k*2.39996+h*.55;
 float2 c=float2(cos(theta),sin(theta))*_Radius*sqrt(h2)*.72;
 float radius=_PuffSize*lerp(.7,1.3,h);
 float d=length(q-c)/max(radius,.001);
 float lobe=exp(-d*d*1.5);
 density=max(density,lobe)+min(density,lobe)*.12;
}
float grain=LearnFbm(q*_DetailScale,seed+73);grain=lerp(grain,color.r,_SourceMix);
float folds=1-abs(LearnNoise(q*_DetailScale+warp*.45,seed+37)*2-1);
grain=lerp(grain,folds,_Fold);
float field=density-(1-grain)*_Detail*.48;
float edge=smoothstep(0,max(.001,_Softness),field);
float a=pow(saturate(1-exp(-max(0,field)*2.2)),_Contrast)*edge;
float border=1-smoothstep(.43,.49,max(abs(tilePoint.x),abs(tilePoint.y)));a*=border;
float tone=lerp(1,lerp(.28,1,smoothstep(.22,.82,grain)),_Relief);
return float4(tone.xxx,saturate(a)*_Opacity);
}
